'use client';

import Link from 'next/link';
import { ArrowRight, Heart, SpeakerHigh } from '@/components/icons';

/*
 * Hero CTA row. Donate + Projects links use next/link; the "Listen
 * to audio tour" button calls the global wired up by AudioTour.
 */
export default function HeroActions() {
  return (
    <div className="hero-btns">
      <Link href="/donate" className="btn-accent">
        <Heart weight="fill" size="1em" aria-hidden="true" /> Donate Now
      </Link>
      <Link href="/projects" className="btn-ghost">
        Our Projects <ArrowRight size="1em" aria-hidden="true" />
      </Link>
      <button
        type="button"
        className="hero-listen"
        aria-label="Listen to an audio tour of this page"
        onClick={() => typeof window !== 'undefined' && window.startAudioTour?.()}
      >
        <SpeakerHigh size="1em" aria-hidden="true" /> Listen to audio tour
      </button>
    </div>
  );
}
/*
 * Decorative rings + eye SVG behind the home hero. Pure presentation;
 * carries aria-hidden so screen readers skip it.
 */
export default function HeroGraphics({ liveLabel }: { liveLabel?: string }) {
  return (
    <div className="hero-graphics" aria-hidden="true">
      <svg className="hg-rings" viewBox="0 0 400 400" fill="none" stroke="currentColor" strokeWidth="1">
        <circle cx="200" cy="200" r="80" />
        <circle cx="200" cy="200" r="130" />
        <circle cx="200" cy="200" r="180" strokeDasharray="4 8" />
      </svg>
      <svg className="hg-eye" viewBox="0 0 220 257.57" fill="currentColor">
        <path d="M212.24,8.45c-5.74-5.63-13.38-8.45-22.94-8.45H0v57.17c13.39-5.17,28.43-8.08,44.32-8.08,32.4,0,61.24,12.06,79.89,30.85,3.56,3.59,3.56,9.32,0,12.9-18.65,18.79-47.49,30.86-79.89,30.86-5.32,0-10.54-.33-15.64-.96-10.14-1.24-19.77-3.69-28.68-7.13v108.45c0,9.77,2.86,17.47,8.6,23.11,5.74,5.63,13.38,8.45,22.94,8.45h189.29v-57.17c-13.4,5.17-28.43,8.08-44.32,8.08-32.4,0-61.25-12.06-79.89-30.85-3.56-3.59-3.56-9.32,0-12.9,18.64-18.79,47.49-30.86,79.89-30.86,5.32,0,10.54.33,15.64.96,10.13,1.24,19.76,3.69,28.68,7.13V31.55c0-9.77-2.86-17.48-8.6-23.11Z" />
      </svg>
      <div className="hg-dots"></div>
      <span className="hg-line l1"></span>
      <span className="hg-line l2"></span>
      {liveLabel ? (
        <span className="hg-live"><span className="dot"></span> {liveLabel}</span>
      ) : null}
    </div>
  );
}
import RichText from '@/components/RichText';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
interface Stat { number?: string; label?: string; [key: string]: any }
export default function ImpactCell({ stat }: { stat?: Stat }) {
  const { number, label } = stat || {};
  return (
    <div className="hi-cell">
      <RichText as="div" className="hi-n" html={number} />
      <div className="hi-l">{label}</div>
    </div>
  );
}
import RichText from '@/components/RichText';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
interface Stat { number?: string; label?: string; [key: string]: any }
export default function StatBlock({ stat }: { stat?: Stat }) {
  const { number, label } = stat || {};
  return (
    <div className="stat-block">
      <RichText as="span" className="num" html={number} />
      <span className="lbl">{label}</span>
    </div>
  );
}
import CmsIcon from '@/components/CmsIcon';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
interface Value { num?: string; icon?: string; title?: string; desc?: string; meta?: string; variant?: string; [key: string]: any }
export default function ValueCard({ value }: { value?: Value }) {
  const { num, icon, title, desc, meta, variant } = value || {};
  return (
    <li className={`val-card ${variant || 'v-brand'}`}>
      <div className="val-num">{num}</div>
      <div className="val-ico"><CmsIcon name={icon} aria-hidden="true" /></div>
      <h3>{title}</h3>
      <p>{desc}</p>
      <div className="val-meta"><span>{meta}</span></div>
    </li>
  );
}
import Link from 'next/link';
import CmsIcon from '@/components/CmsIcon';
import { ArrowRight } from '@/components/icons';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
interface Feature { icon?: string; title?: string; desc?: string; [key: string]: any }
export default function FeatureCard({ feature }: { feature?: Feature }) {
  const { icon, title, desc } = feature || {};
  return (
    <div className="feature-card">
      <div className="feature-icon"><CmsIcon name={icon} aria-hidden="true" /></div>
      <h3>{title}</h3>
      <p>{desc}</p>
      <Link className="card-link" href="/projects">
        Learn more <ArrowRight size="1em" aria-hidden="true" />
      </Link>
    </div>
  );
}

import Link from 'next/link';
import { isSafeImageUrl } from '@/lib/utils';

/*
 * Shared story/blog card. Used on the home page "Latest Stories"
 * grid and on /documents.
 *
 * `story` shape (CMS): { title, desc, heroType, tagClass, tagLabel,
 *   img, initials, author, meta, readTime }.
 * `featured` adds the .featured modifier class.
 */
export interface StoryCardData {
  heroType?: string;
  tagClass?: string;
  tagLabel?: string;
  img?: string;
  title?: string;
  desc?: string;
  initials?: string;
  author?: string;
  meta?: string;
  readTime?: string;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any;
}

interface StoryCardProps {
  story?: StoryCardData;
  featured?: boolean;
}

export default function StoryCard({ story, featured = false }: StoryCardProps) {
  const {
    heroType = 'type-story',
    tagClass = 'story',
    tagLabel = 'Story',
    img,
    title,
    desc,
    initials = 'TE',
    author = '',
    meta,
    readTime,
  } = story || {};

  const href = heroType === 'type-blog' ? '/documents#blogs' : '/documents#stories';
  const safeImg = isSafeImageUrl(img) ? img : '';
  const bgStyle = safeImg
    ? {
        backgroundImage: `linear-gradient(180deg, rgba(0,0,0,.05) 30%, rgba(13,4,7,.75) 100%), url('${safeImg}')`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
      }
    : undefined;

  return (
    <Link
      className={`doc-card${featured ? ' featured' : ''}`}
      href={href}
      aria-label={title}
    >
      <div className={`doc-hero ${heroType}`} style={bgStyle}>
        <div>
          <span className={`cat-tag ${tagClass}`}>{tagLabel}</span>
          <h3>{title}</h3>
        </div>
      </div>
      <div className="doc-body">
        <p>{desc}</p>
        <div className="doc-meta">
          <div className="doc-author">
            <div className="avatar">{initials}</div>
            <span>{author}</span>
          </div>
          <span className="sep">·</span>
          <span>{meta || readTime || ''}</span>
        </div>
      </div>
    </Link>
  );
}
import Link from 'next/link';

/*
 * Row in the story timeline (home archive + any future archive view).
 * `story` shape: { date, location, title, desc, initials, author, meta }.
 * Date is space-separated "Month Day" (e.g. "Apr 12").
 */
export interface TimelineRowData {
  date?: string;
  location?: string;
  title?: string;
  desc?: string;
  initials?: string;
  author?: string;
  meta?: string;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any;
}

export default function TimelineRow({ story }: { story?: TimelineRowData }) {
  const { date = '', location, title, desc, initials = 'TE', author = '', meta } = story || {};
  const [month = '', day = ''] = date.split(' ');

  return (
    <li className="story-row">
      <Link href="/documents#stories" className="story-row-link" aria-label={title}>
        <div className="sr-rail"><span className="sr-dot"></span></div>
        <div className="sr-date">
          <div className="sr-month">{month}</div>
          <div className="sr-day">{day}</div>
        </div>
        <div className="sr-body">
          <div className="sr-tags">
            <span className="cat-tag story">Story</span>
            {location ? <span className="sr-loc">{location}</span> : null}
          </div>
          <h4>{title}</h4>
          <p>{desc}</p>
          <div className="sr-meta">
            <div className="avatar sm">{initials}</div>
            <span>{author}</span>
            <span className="sep">·</span>
            <span>{meta || ''}</span>
          </div>
        </div>
      </Link>
    </li>
  );
}
import Link from 'next/link';
import CmsIcon from '@/components/CmsIcon';
import { ArrowRight } from '@/components/icons';

/*
 * Card that renders a single project in the /projects grid.
 *
 * CMS shape: { id, slug, icon, title, desc, tag, status, visible, order }.
 * When `slug` is present, the entire card becomes a link to
 * /projects/<slug>. Legacy items without a slug render as a plain div.
 */
export interface Project {
  id?: string;
  slug?: string;
  icon?: string;
  title?: string;
  desc?: string;
  tag?: string;
  status?: string;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any;
}
export default function ProjectCard({ project }: { project?: Project }) {
  const { icon, title, desc, tag, slug, status } = project || {};
  const statusClass = status ? ` prog-card-${status}` : '';

  const inner = (
    <>
      <div className="prog-icon">
        <CmsIcon name={icon || 'star'} aria-hidden="true" />
      </div>
      <div className="prog-content">
        <h3>{title || ''}</h3>
        <p>{desc || ''}</p>
        {tag ? <span className="prog-tag">{tag}</span> : null}
        {slug ? (
          <span className="prog-learn-more" aria-hidden="true">
            Learn more <ArrowRight size="1em" aria-hidden="true" />
          </span>
        ) : null}
      </div>
    </>
  );

  if (slug) {
    return (
      <Link
        href={`/projects/${slug}`}
        className={`prog-card prog-card-link${statusClass}`}
        aria-label={`${title} — learn more`}
      >
        {inner}
      </Link>
    );
  }

  return <div className={`prog-card${statusClass}`}>{inner}</div>;
}

