'use client';

import Link from 'next/link';
import { ArrowRight, Heart, SpeakerHigh } from '@/components/icons';

/*
 * Hero CTA row. Donate is the gold primary action (house rule: gold
 * fills always take var(--brand-fg) text); Projects is the gold-outline
