 * up by AudioTour.
 */
export default function HeroActions() {
  return (
    <div className="hero-btns">
      <Link href="/donate" className="btn-primary">
        <Heart weight="fill" size="1em" aria-hidden="true" /> Donate Now
      </Link>
      <Link href="/projects" className="btn-secondary">
        Our Projects <ArrowRight size="1em" aria-hidden="true" />
      </Link>
      <button
        type="button"
        className="hero-listen"
        aria-label="Listen to an audio tour of this page"
        onClick={() => typeof window !== 'undefined' && window.startAudioTour?.()}
      >
        <SpeakerHigh size="1em" aria-hidden="true" /> Listen to audio tour
      </button>
    </div>
  );
}

import CmsIcon from '@/components/CmsIcon';

/*
 * Core value as a numbered editorial row (not a card): oversized
 * pale-gold Literata numeral · title + description · icon + meta.
 * All CMS fields keep rendering: num, icon, variant, title, desc, meta.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
interface Value { num?: string; icon?: string; title?: string; desc?: string; meta?: string; variant?: string; [key: string]: any }
export default function ValueCard({ value }: { value?: Value }) {
  const { num, icon, title, desc, meta, variant } = value || {};
  return (
    <li className={`val-row ${variant || 'v-brand'}`}>
      <span className="val-num">{num}</span>
      <div className="val-body">
        <h3>{title}</h3>
        <p>{desc}</p>
      </div>
      <div className="val-aside">
        <span className="val-ico"><CmsIcon name={icon} aria-hidden="true" /></span>
        <span className="val-meta">{meta}</span>
      </div>
    </li>
  );
}

