  .hero-impact .hi-cell:nth-child(3) { border-top: 1px solid rgba(255,255,255,.14); }
  .hero-impact .hi-cell:nth-child(4) { border-top: 1px solid rgba(255,255,255,.14); }
  .hero-impact .hi-cell:nth-child(3),
  .hero-impact .hi-cell:nth-child(4) { padding-top: 14px; }
}
@media (max-width: 420px) {
  .hero-impact { grid-template-columns: 1fr; }
  .hero-impact .hi-cell { border-right: none !important; padding-left: 0 !important; padding-right: 0 !important; }
  .hero-impact .hi-cell + .hi-cell { border-top: 1px solid rgba(255,255,255,.14); padding-top: 14px; }

input.new_string:
  .hero-impact { grid-template-columns: repeat(2, 1fr); }
  .hero-impact .hi-cell:nth-child(2) { border-right: none; }
  .hero-impact .hi-cell:nth-child(3) { border-top: 1px solid var(--border); }
  .hero-impact .hi-cell:nth-child(4) { border-top: 1px solid var(--border); }
  .hero-impact .hi-cell:nth-child(3),
  .hero-impact .hi-cell:nth-child(4) { padding-top: 14px; }
}
@media (max-width: 420px) {
  .hero-impact { grid-template-columns: 1fr; }
  .hero-impact .hi-cell { border-right: none !important; padding-left: 0 !important; padding-right: 0 !important; }
  .hero-impact .hi-cell + .hi-cell { border-top: 1px solid var(--border); padding-top: 14px; }

input.content:
/* ── CORE VALUES — numbered editorial rows ─────────────────── */
.values-section {
  position: relative; overflow: hidden;
  padding: 110px var(--space-8) 120px;
  background: var(--bg);
  border-top: 1px solid var(--border);
}
.values-inner { position: relative; z-index: 1; }
.values-head { max-width: 780px; margin-bottom: 64px; }
.values-head .section-eyebrow { margin-bottom: 14px; }

/* Quiet braille ornament — real braille spelling "teww" (⠞⠑⠺⠺). */
.values-braille {
  position: absolute; top: 96px; right: var(--space-8);
  font-size: clamp(3.5rem, 7vw, 6rem);
  letter-spacing: .16em; line-height: 1;
  color: var(--brand);
  opacity: .14;
  pointer-events: none; user-select: none;
}
[data-theme="high-contrast"] .values-braille { display: none; }
@media (max-width: 1080px) { .values-braille { display: none; } }

.values-title {
  font-family: var(--font-display); font-weight: 600;
  font-size: var(--text-title);
  letter-spacing: -.015em; line-height: 1.1;
  color: var(--fg); margin-bottom: 18px; text-wrap: balance;
}
/* House style: <em> in CMS titles = Literata italic in gold. */
.values-title em { font-style: italic; color: var(--brand); }
.values-sub {
  font-size: 1.08rem; color: var(--fg-muted); line-height: 1.65; max-width: 62ch;
}

.values-list {
  list-style: none; padding: 0; margin: 0;
  border-top: 1px solid color-mix(in oklab, var(--brand) 40%, transparent);
}
.val-row {
  display: grid;
  grid-template-columns: minmax(96px, 150px) minmax(0, 1fr) minmax(180px, 230px);
  gap: 32px;
  align-items: start;
  padding: 44px 0 40px;
  border-bottom: 1px solid var(--border);
}
.val-num {
  font-family: var(--font-display);
  font-size: clamp(2.6rem, 4.5vw, 4.25rem);
  font-weight: 300;
  line-height: .9;
  letter-spacing: -.02em;
  font-variant-numeric: tabular-nums;
  color: color-mix(in oklab, var(--brand) 62%, var(--bg));
}
[data-theme="high-contrast"] .val-num { color: var(--brand); }
.val-body h3 {
  font-family: var(--font-display); font-weight: 600;
  font-size: clamp(1.25rem, 1.9vw, 1.6rem);
  letter-spacing: -.015em; line-height: 1.2;
  color: var(--fg); margin-bottom: 10px;
  text-wrap: balance;
}
.val-body p {
  font-size: .98rem; color: var(--fg-muted);
  line-height: 1.65; max-width: 60ch;
}
.val-aside {
  display: flex; flex-direction: column;
  align-items: flex-start; gap: 14px;
  padding-top: 4px;
}
.val-ico {
  width: 44px; height: 44px; border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  font-size: 20px;
  background: var(--brand-subtle); color: var(--brand);
  border: 1px solid color-mix(in oklab, var(--brand) 25%, transparent);
}
.val-meta {
  font-family: var(--font-body);
  font-size: .68rem; font-weight: 700;
  letter-spacing: .16em; text-transform: uppercase;
  color: var(--fg-muted);
  display: inline-flex; align-items: center; gap: 8px;
}
.val-meta::before { content: ''; width: 18px; height: 1px; background: var(--brand); flex-shrink: 0; }
/* CMS variant field keeps steering the icon tint. */
.val-row.v-accent .val-ico { background: var(--accent-subtle); color: var(--accent); border-color: color-mix(in oklab, var(--accent) 25%, transparent); }
.val-row.v-ink .val-ico { background: var(--bg-subtle); color: var(--fg); border-color: var(--border-strong); }

@media (max-width: 860px) {
  .val-row { grid-template-columns: 72px minmax(0, 1fr); gap: 20px; padding: 34px 0 30px; }
  .val-aside { grid-column: 2; flex-direction: row; align-items: center; padding-top: 4px; }
}
@media (max-width: 480px) {
  .val-row { grid-template-columns: 56px minmax(0, 1fr); gap: 16px; }
  .val-num { font-size: 2.2rem; }
}

/* ── STORY TIMELINE (the archive) ───────────────────── */
.story-timeline {
  padding: 110px var(--space-8) 120px;
  background: var(--bg);
  border-top: 1px solid var(--border);
  position: relative;
}
.story-head { max-width: 820px; margin-bottom: 56px; }
.story-eyebrow {
  display: inline-flex; align-items: center; gap: 10px;
  font-family: var(--font-body);
  font-size: .74rem; font-weight: 700;
  letter-spacing: .18em; text-transform: uppercase;
  color: var(--brand);
  margin-bottom: 20px;
}
.story-eyebrow .ribbon-dot {
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--brand); box-shadow: 0 0 0 3px var(--brand-subtle);
}
.story-eyebrow .story-count { color: var(--fg-subtle); letter-spacing: .12em; }
.story-h2 {
  font-family: var(--font-display); font-weight: 600;
  font-size: var(--text-title);
  letter-spacing: -.015em; line-height: 1.12;
  color: var(--fg);
  /* text-wrap: balance interacts badly with <br> inside the heading and
     causes "Every story we've / published," line breaks on some viewports.
     `pretty` keeps the explicit <br> as the only break and prevents orphans. */
  text-wrap: pretty;
  max-width: 26ch;
  word-break: normal;
  overflow-wrap: break-word;
}
.story-h2 br { display: block; }
.story-h2 em { font-style: italic; color: var(--brand); }

/* Featured story — night-editorial split card */
.story-featured {
  display: grid;
  grid-template-columns: minmax(0, .95fr) minmax(0, 1.05fr);
  gap: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg-elevated);
  cursor: pointer;
  transition: border-color .25s, transform .25s, box-shadow .25s;
  margin-bottom: 72px;
  text-decoration: none;
  color: inherit;
}
.story-featured:hover {
  border-color: var(--border-strong);
  transform: translateY(-2px);
}
[data-theme="light"] .story-featured:hover { box-shadow: var(--shadow-md); }
/* min-width: 0 so long titles don't force the body track wider than its share. */
.story-featured > * { min-width: 0; }
.sf-media {
  position: relative; min-height: 380px;
  background: var(--bg-subtle);
  border-right: 1px solid var(--border);
  overflow: hidden;
}
.sf-photo {
  position: absolute; inset: 0;
  background: radial-gradient(460px 460px at 62% 45%, var(--brand-subtle), transparent 72%);
}
.sf-rings {
  position: absolute; inset: 0; width: 100%; height: 100%;
  color: color-mix(in oklab, var(--brand) 38%, transparent);
}
.sf-badge {
  position: absolute; top: 20px; left: 20px;
  display: inline-flex; align-items: center; gap: 8px;
  padding: 9px 14px;
  background: var(--brand);
  color: var(--brand-fg);
  border-radius: var(--radius-full);
  font-family: var(--font-body);
  font-size: .68rem; font-weight: 800;
  letter-spacing: .14em; text-transform: uppercase;
}
.sf-badge i { font-size: 14px; }

.sf-body {
  padding: 48px 44px 40px;
  display: flex; flex-direction: column;
  gap: 22px;
}
.sf-meta-top {
  display: flex; align-items: center; gap: 14px;
  flex-wrap: wrap;
  font-family: var(--font-body);
  font-size: .74rem; font-weight: 700;
  letter-spacing: .1em; text-transform: uppercase;
  color: var(--brand);
}
.sf-meta-top .sf-date,
.sf-meta-top .sf-read {
  display: inline-flex; align-items: center; gap: 6px;
}
.sf-title {
  font-family: var(--font-display); font-style: italic; font-weight: 600;
  font-size: clamp(1.5rem, 2.4vw, 2.05rem);
  letter-spacing: -.015em; line-height: 1.18;
  color: var(--fg);
  text-wrap: pretty;
  word-break: normal;
  overflow-wrap: break-word;
  hyphens: auto;
}
.sf-title em { color: var(--brand); }
.sf-excerpt {
  font-size: 1.02rem; color: var(--fg-muted); line-height: 1.65;
  overflow-wrap: break-word;
  hyphens: auto;
}
.sf-footer {
  display: flex; align-items: center; justify-content: space-between;
  gap: 16px; flex-wrap: wrap;
  padding-top: 22px; margin-top: auto;
  border-top: 1px solid color-mix(in oklab, var(--brand) 35%, transparent);
}
.sf-author { display: flex; align-items: center; gap: 12px; }
.avatar.lg {
  width: 44px; height: 44px; font-size: .82rem;
  background: var(--brand-subtle); color: var(--brand);
  border: 1px solid color-mix(in oklab, var(--brand) 35%, transparent);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-display); font-weight: 700; letter-spacing: .04em;
}
.avatar.sm {
  width: 28px; height: 28px; font-size: .64rem;
  background: var(--brand-subtle); color: var(--brand);
  border: 1px solid color-mix(in oklab, var(--brand) 30%, transparent);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-display); font-weight: 700; letter-spacing: .04em;
}
.sf-author-name { font-family: var(--font-body); font-weight: 700; color: var(--fg); font-size: .92rem; }
.sf-author-role { font-size: .78rem; color: var(--fg-muted); }
.sf-read-btn {
  border: 1px solid var(--brand); background: transparent; color: var(--brand);
  padding: 11px 18px; border-radius: var(--radius-full);
  font-family: var(--font-body); font-weight: 700; font-size: .86rem;
  cursor: pointer;
  display: inline-flex; align-items: center; gap: 8px;
  transition: background .2s, color .2s;
}
.story-featured:hover .sf-read-btn { background: var(--brand); color: var(--brand-fg); }

/* Timeline list — archive rows on a hairline rail */
.story-list {
  list-style: none; padding: 0;
  display: flex; flex-direction: column;
  border-left: 1px dashed var(--border);
  margin-left: 58px;
}
/*
 * A TimelineRow is wrapped in a next/link (.story-row-link) to make
 * the whole row clickable. That wrapper must be the grid container —
 * if we put `display: grid` on the <li>, the Link sits as a single
 * grid item in the first 42px track and squeezes all the row content
 * into a 42px column.
 */
.story-row {
  border-bottom: 1px solid var(--border);
  margin-left: -59px;
  position: relative;
}
.story-row:last-child { border-bottom: none; }
.story-row-link {
  display: grid;
  grid-template-columns: 42px 96px minmax(0, 1fr);
  gap: 24px;
  padding: 30px 0;
  cursor: pointer;
  transition: background .2s;
  text-decoration: none;
  color: inherit;
}
.story-row-link:hover { background: var(--bg-elevated); }
.story-row-link > * { min-width: 0; }
.sr-rail {
  position: relative;
  display: flex; align-items: flex-start; justify-content: center;
  padding-top: 8px;
}
.sr-dot {
  width: 12px; height: 12px; border-radius: 50%;
  background: var(--bg); border: 2px solid var(--fg-subtle);
  transition: border-color .2s, background .2s, transform .2s;
}
.story-row-link:hover .sr-dot { border-color: var(--brand); background: var(--brand); transform: scale(1.15); }
.sr-date {
  font-family: var(--font-display);
  text-align: left;
  padding-top: 2px;
}
.sr-month {
  font-family: var(--font-body);
  font-size: .68rem; font-weight: 700; letter-spacing: .18em;
  text-transform: uppercase; color: var(--brand);
}
.sr-day {
  font-family: var(--font-display);
  font-size: 2.6rem; font-weight: 300; color: var(--fg);
  letter-spacing: -.02em; line-height: 1;
  font-variant-numeric: tabular-nums;
}
.sr-body { padding-right: 10px; }
.sr-tags {
  display: flex; align-items: center; gap: 10px;
  margin-bottom: 10px; flex-wrap: wrap;
}
.sr-loc {
  font-family: var(--font-body);
  font-size: .7rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase;
  color: var(--fg-subtle);
}
.sr-body h4 {
  font-family: var(--font-display); font-style: italic; font-weight: 600;
  font-size: 1.25rem; letter-spacing: -.015em; line-height: 1.25;
  color: var(--fg); margin-bottom: 8px;
  text-wrap: balance;
  transition: color .2s;
}
.story-row-link:hover .sr-body h4 { color: var(--brand); }
.sr-body p {
  font-size: .94rem; color: var(--fg-muted);
  line-height: 1.6;
  margin-bottom: 14px;
  max-width: 70ch;
}
.sr-meta {
  display: flex; align-items: center; gap: 8px;
  font-family: var(--font-body);
  font-size: .8rem; color: var(--fg-muted);
}
.sr-meta .sep { color: var(--fg-subtle); }

/* Footer */
.story-foot {
  display: flex; align-items: center; justify-content: space-between;
  gap: 16px; flex-wrap: wrap;
  margin-top: 48px;
  padding-top: 30px;
  border-top: 1px solid color-mix(in oklab, var(--brand) 35%, transparent);
}
.story-foot-meta {
  font-family: var(--font-body);
  font-size: .72rem; letter-spacing: .12em; text-transform: uppercase;
  color: var(--fg-subtle); font-weight: 700;
}

/* Collapse the two-column featured-story card below ~desktop width so the
   body never gets squeezed into a one-word-per-line strip. */
@media (max-width: 1040px) {
  .story-featured { grid-template-columns: 1fr; }
  .sf-media { min-height: 240px; border-right: none; border-bottom: 1px solid var(--border); }
  .sf-body { padding: 32px 28px; }
}
@media (max-width: 900px) {
  .story-list { margin-left: 0; border-left: none; }
  .story-row { margin-left: 0; }
  .story-row-link { grid-template-columns: 74px minmax(0, 1fr); }
  .sr-rail { display: none; }
}
@media (max-width: 520px) {
  .sf-body { padding: 24px 20px; gap: 16px; }
  .sr-day { font-size: 2rem; }
}

/*
 * Home extras — night-first restyles owned by the home page.
 * Loads after 02/05/10/17, so equal-specificity overrides here win;
 * everything is scoped to home-only hooks (.stats-band, .home-projects-grid,
 * .home-stories, .story-timeline) to stay out of other pages' way.
 */

/* ── Hero echo-ripple keyframes (rules live in 02, .hero* scope) ── */
@keyframes hgBreathe {
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(1.045); }
}
/* Each ring dips toward ~45% of its own base opacity, staggered per
   ring, so the field reads as a slow outward echo. */
@keyframes hgWave {
  0%, 100% { opacity: var(--o, .2); }
  50%      { opacity: calc(var(--o, .2) * .45); }
}
/* hg-core reuses hgBreathe via transform — translate must persist. */
.hero-graphics .hg-core { animation-name: hgCorePulse; }
@keyframes hgCorePulse {
  0%, 100% { transform: translate(-50%, -50%) scale(1); }
  50%      { transform: translate(-50%, -50%) scale(1.25); }
}

/* ── Stats band — flat editorial numerals between hairlines ────── */
.stats-band,
[data-theme="light"] .stats-band,
[data-theme="dark"] .stats-band,
[data-theme="high-contrast"] .stats-band {
  background: var(--bg);
  color: var(--fg);
  padding: 76px var(--space-8);
  border-bottom: 1px solid var(--border);
}
.stats-band .section-inner {
  grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
  gap: 40px;
}
.stat-block,
[data-theme="dark"] .stat-block,
[data-theme="high-contrast"] .stat-block {
  text-align: left;
  border-left: 1px solid var(--border);
  padding-left: 28px;
}
.stat-block .num,
[data-theme="dark"] .stat-block .num,
[data-theme="high-contrast"] .stat-block .num {
  font-family: var(--font-display);
  font-size: clamp(2.8rem, 4.2vw, 4rem);
  font-weight: 300;
  letter-spacing: -.02em;
  line-height: 1;
  color: var(--fg);
  display: block;
  font-variant-numeric: tabular-nums;
}
.stat-block .num em { color: var(--brand); font-style: normal; }
.stat-block .lbl {
  display: block;
  font-size: .9rem; color: var(--fg-muted); opacity: 1;
  margin-top: 12px; line-height: 1.5; max-width: 32ch;
}

/* ── "What We Build" — night cards with status chips ───────────── */
.home-projects-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 20px;
  margin-top: 8px;
}
.home-projects-grid .prog-card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: none;
  padding: 28px;
  transition: border-color .2s, transform .2s, box-shadow .2s;
}
.home-projects-grid .prog-card:hover {
  border-color: var(--border-strong);
  transform: translateY(-2px);
  box-shadow: none;
}
[data-theme="light"] .home-projects-grid .prog-card:hover { box-shadow: var(--shadow-md); }
.home-projects-grid .prog-icon {
  width: 48px; height: 48px; border-radius: var(--radius-md);
  background: var(--brand-subtle); color: var(--brand);
  font-size: 22px;
}
.home-projects-grid .prog-content h3 {
  font-weight: 600; font-size: 1.2rem; letter-spacing: -.015em;
}
/* Status chip: the CMS tag text names the state (never color alone);
   status class tints it. */
.home-projects-grid .prog-tag {
  display: inline-flex; align-items: center; gap: 7px;
  background: transparent;
  border: 1px solid color-mix(in oklab, var(--brand) 45%, transparent);
  color: var(--brand);
}
.home-projects-grid .prog-tag::before {
  content: ''; width: 6px; height: 6px; border-radius: 50%;
  background: currentColor; flex-shrink: 0;
}
.home-projects-grid .prog-card-in-progress .prog-tag {
  border-color: color-mix(in oklab, var(--accent) 45%, transparent);
  color: var(--accent);
}
.home-projects-grid .prog-card-coming-soon .prog-tag {
  border-color: var(--border-strong);
  color: var(--fg-muted);
}

/* ── Latest stories — night-editorial cards (scoped: /documents keeps
      its own styling of the shared StoryCard markup) ─────────────── */
.home-stories { border-top: 1px solid var(--border); }
.home-stories .doc-card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: none;
  transition: border-color .2s, transform .2s, box-shadow .2s;
}
.home-stories .doc-card:hover {
  border-color: var(--border-strong);
  transform: translateY(-2px);
  box-shadow: none;
}
[data-theme="light"] .home-stories .doc-card:hover { box-shadow: var(--shadow-md); }
/* One flat night panel replaces every legacy gradient tile. */
.home-stories .doc-hero {
  background: var(--bg-subtle);
  color: var(--fg);
  border-bottom: 1px solid var(--border);
}
/* Quiet echo arcs in the tile corner (decorative, css-only). */
.home-stories .doc-hero::before,
.home-stories .doc-hero::after {
  content: ''; position: absolute; border-radius: 50%;
  border: 1px solid color-mix(in oklab, var(--brand) 30%, transparent);
  pointer-events: none;
}
.home-stories .doc-hero::before { width: 190px; height: 190px; right: -70px; top: -70px; }
.home-stories .doc-hero::after  { width: 310px; height: 310px; right: -130px; top: -130px; border-color: color-mix(in oklab, var(--brand) 16%, transparent); }
[data-theme="high-contrast"] .home-stories .doc-hero::before,
[data-theme="high-contrast"] .home-stories .doc-hero::after { display: none; }
.home-stories .doc-hero > div { position: relative; z-index: 1; }
.home-stories .doc-hero h3 {
  font-family: var(--font-display); font-style: italic; font-weight: 600;
  font-size: 1.45rem; letter-spacing: -.015em; line-height: 1.22;
  color: var(--fg);
}
.home-stories .doc-card.featured .doc-hero h3 { font-size: 1.85rem; }
.home-stories .doc-hero .cat-tag {
  background: transparent;
  border: 1px solid color-mix(in oklab, var(--brand) 45%, transparent);
  color: var(--brand);
  backdrop-filter: none;
  font-family: var(--font-body);
}
/* Gold meta line under the excerpt. */
.home-stories .doc-meta {
  border-top: 1px solid color-mix(in oklab, var(--brand) 35%, transparent);
  padding-top: 14px; margin-top: 6px;
  font-family: var(--font-body);
  font-size: .78rem; font-weight: 600; letter-spacing: .04em;
  color: var(--fg-muted);
}
.home-stories .doc-author .avatar {
  background: var(--brand-subtle);
