   generic fix in 10-responsive-fixes.css by source order). */
.home-stories .cat-tag.story, .home-stories .cat-tag.blog,
.sf-meta-top .cat-tag.story, .sr-tags .cat-tag.story,
.sf-meta-top .cat-tag.blog, .sr-tags .cat-tag.blog {
  background: var(--brand-subtle);
  color: var(--brand);
  backdrop-filter: none;
}

